
.home{width:280px;margin-left:auto;margin-right:auto
}
.home-title{margin-bottom:24px;color:var(--ink);font-size:46px;font-weight:700;line-height:1;text-align:center
}
.home-name{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;-webkit-box-sizing:border-box;box-sizing:border-box;height:56px;margin-bottom:24px;padding:0 12px;border:2px solid var(--line);border-radius:8px;-webkit-box-shadow:0 3px 0 var(--lip);box-shadow:0 3px 0 var(--lip);background:var(--answer);color:#fff;font-size:26px;font-weight:700;line-height:1;overflow:hidden;white-space:nowrap;cursor:pointer;-webkit-user-select:none;-moz-user-select:none;-ms-user-select:none;user-select:none
}
.home-name:active{-webkit-transform:translateY(2px);transform:translateY(2px);-webkit-box-shadow:0 1px 0 var(--lip);box-shadow:0 1px 0 var(--lip)
}
.mode-tile{position:relative;display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;-webkit-box-sizing:border-box;box-sizing:border-box;height:120px;margin-bottom:14px;border:2px solid var(--line);border-radius:8px;-webkit-box-shadow:0 3px 0 var(--lip);box-shadow:0 3px 0 var(--lip);background:var(--tile);color:var(--ink);font-size:44px;font-weight:700;line-height:1;cursor:pointer;-webkit-user-select:none;-moz-user-select:none;-ms-user-select:none;user-select:none
}
.mode-tile:active{-webkit-transform:translateY(2px);transform:translateY(2px);-webkit-box-shadow:0 1px 0 var(--lip);box-shadow:0 1px 0 var(--lip)
}
.home-chrome{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;gap:16px
}
.home-chrome .help-icon{margin:22px 0 0
}
.gear-icon svg{display:block;width:26px;height:26px
}
.settings-done{-webkit-box-sizing:border-box;box-sizing:border-box;width:130px;height:48px;margin-top:22px;padding:0;border:2px solid var(--line);border-radius:8px;-webkit-box-shadow:0 3px 0 var(--lip);box-shadow:0 3px 0 var(--lip);background:var(--ink);color:var(--tile);font-family:inherit;font-size:20px;font-weight:700;line-height:1;cursor:pointer
}
.settings-done:active{-webkit-transform:translateY(2px);transform:translateY(2px);-webkit-box-shadow:0 1px 0 var(--lip);box-shadow:0 1px 0 var(--lip)
}
.mode-why{position:absolute;top:10px;right:10px;display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;width:32px;height:32px;padding:0;border:none;border-radius:50%;background:var(--ink);color:var(--tile);font-family:inherit;font-size:18px;font-weight:700;line-height:1;cursor:pointer
}
.note-veil{position:fixed;left:0;top:0;right:0;bottom:0;display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;background:rgba(0,0,0,.4);z-index:20
}
.note-card{-webkit-box-sizing:border-box;box-sizing:border-box;width:290px;padding:24px;border:2px solid var(--line);border-radius:8px;-webkit-box-shadow:0 3px 0 var(--lip);box-shadow:0 3px 0 var(--lip);background:var(--tile);color:var(--ink);text-align:center
}
.note-title{font-size:28px;font-weight:700;line-height:1;margin-bottom:12px
}
.note-body{font-size:18px;line-height:1.35
}
.note-close{margin-top:12px;color:var(--muted);font-size:14px
}
.note-card.settings-card{width:320px;padding:22px
}
.about-body{font-size:16px;line-height:1.35
}
.about-body+.about-body{margin-top:12px
}
.about-credit{margin-top:14px;font-size:14px;line-height:1.5
}
.about-credit a{color:var(--mark-on);text-decoration:none
}
.note-title.settings-title{margin-bottom:16px
}


