
.tick-counter{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-orient:vertical;-webkit-box-direction:normal;-ms-flex-direction:column;flex-direction:column;gap:8px;margin:0
}
.tick-counter DIV{background:var(--tile);width:44px;height:44px;border:2px solid var(--line);border-radius:8px;-webkit-box-shadow:0 2px 0 var(--lip);box-shadow:0 2px 0 var(--lip);line-height:40px;font-size:18px;font-weight:700;color:var(--ink)
}


