
.gridfacts{width:340px;margin:0 auto;cursor:pointer;-webkit-user-select:none;-moz-user-select:none;-ms-user-select:none;user-select:none
}
.gridfacts-table{width:340px;border-collapse:collapse;table-layout:fixed;outline:1px solid var(--paper)
}
.gridfacts-table td{width:34px;height:28px;font-size:20px;font-weight:700;line-height:1;text-align:center;border:1px solid var(--paper)
}
.gridfacts-corner{background:var(--ink);color:var(--tile);font-size:22px
}
.gridfacts-edge{background:var(--operand);color:#1a2744
}
.gridfacts-cell{background:var(--ink);color:var(--tile)
}
.gridfacts-cell.diagonal{background:var(--answer);color:#fff
}
.gridfacts-back{margin-top:20px;color:var(--muted);font-size:16px;text-align:center
}


