
.pass-veil{position:fixed;left:0;top:0;right:0;bottom:0;display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;background:rgba(0,0,0,.45);z-index:30
}
.pass-card{-webkit-box-sizing:border-box;box-sizing:border-box;width:290px;padding:26px;border:2px solid var(--line);border-radius:8px;-webkit-box-shadow:0 3px 0 var(--lip);box-shadow:0 3px 0 var(--lip);background:var(--tile);color:var(--ink);text-align:center
}
.pass-title{font-size:30px;font-weight:700;line-height:1
}
.pass-score{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;width:104px;height:104px;margin:14px auto 0;border-radius:50%;background:var(--answer);color:#fff;font-size:46px;font-weight:700;line-height:1
}
.pass-best{margin-top:14px;color:var(--answer);font-size:17px;font-weight:700
}
.pass-detail{margin-top:14px;color:var(--muted);font-size:16px
}
.pass-buttons{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;gap:10px;margin-top:18px
}
.pass-button{-webkit-box-sizing:border-box;box-sizing:border-box;width:108px;height:48px;padding:0;border:2px solid var(--line);border-radius:8px;-webkit-box-shadow:0 3px 0 var(--lip);box-shadow:0 3px 0 var(--lip);font-family:inherit;font-size:20px;font-weight:700;line-height:1;cursor:pointer
}
.pass-button:active{-webkit-transform:translateY(2px);transform:translateY(2px);-webkit-box-shadow:0 1px 0 var(--lip);box-shadow:0 1px 0 var(--lip)
}
.pass-button.is-wide{width:150px
}
.pass-again{background:var(--tile);color:var(--ink)
}
.pass-done{background:var(--ink);color:var(--tile)
}


