
.squares DIV.level-label{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-orient:vertical;-webkit-box-direction:normal;-ms-flex-direction:column;flex-direction:column;-webkit-box-align:center;-ms-flex-align:center;align-items:center;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;-webkit-box-sizing:border-box;box-sizing:border-box;width:100%;height:100%;margin:0;padding:4px 6px;gap:2px;border:none;border-radius:0;-webkit-box-shadow:none;box-shadow:none;background:rgba(0,0,0,0);-webkit-transform:none;transform:none;font-size:24px;font-weight:700;line-height:1;color:inherit;cursor:inherit
}
.level-label>SPAN{-webkit-box-flex:0;-ms-flex:none;flex:none;font-size:24px;font-weight:700;line-height:1
}
.squares DIV.level-mark{position:relative;-webkit-box-flex:0;-ms-flex:none;flex:none;width:34px;height:34px;margin:0;padding:0;border:none;border-radius:0;-webkit-box-shadow:none;box-shadow:none;background:rgba(0,0,0,0);-webkit-transform:none;transform:none;font-size:0;line-height:0;color:inherit;cursor:inherit
