body .squares DIV.level-label:active,body .squares DIV.level-mark:active{-webkit-transform:none;transform:none;-webkit-box-shadow:none;box-shadow:none
}
.level-mark>.level-score{position:absolute;left:50%;top:50%;-webkit-transform:translate(-50%, -50%);transform:translate(-50%, -50%);display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;width:28px;height:28px;border-radius:50%;background:rgba(7,14,11,.5);-webkit-box-shadow:inset 0 0 0 1.5px rgba(244,240,228,.85);box-shadow:inset 0 0 0 1.5px rgba(244,240,228,.85);font-size:15px;font-weight:700;line-height:1;color:var(--mark-off)
}


