
:root{--paper: #12211B;--ink: #F4F0E4;--tile: #1C3328;--line: #E6E0D0;--lip: #070E0B;--operand: #F0B429;--answer: #1C7A45;--miss: #FF8A82;--mark-on: #8FCBAA;--mark-off: #F0C36A;--grid: rgba(244, 240, 228, 0.07);--muted: #A8B5A4;--track: #2C463A;--level: #C98FC4;--level-text: #12211B;--passed-dot-on: #1C7A45;--passed-dot-off: #C4841A
