.help-icon{-webkit-box-sizing:border-box;box-sizing:border-box;display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;width:52px;height:52px;margin:22px auto 0;padding:0;border:2px solid var(--line);border-radius:50%;background:var(--answer);color:#fff;-webkit-box-shadow:0 3px 0 var(--lip);box-shadow:0 3px 0 var(--lip);font-family:inherit;font-size:28px;font-weight:700;line-height:1;cursor:pointer
