}
.type-ahead-group>ul{background-color:var(--tile);border-radius:8px;border:2px solid var(--line);-webkit-box-shadow:0 3px 0 var(--lip);box-shadow:0 3px 0 var(--lip);display:none;float:left;font-size:22px;left:0;list-style:none;margin:8px 0 0;min-width:170px;padding:5px 0;position:absolute;text-align:left;top:100%;z-index:1000
