
.dice{width:120px;height:120px;margin-left:auto;margin-right:auto;background:var(--tile);margin-top:0;margin-bottom:0;border:2px solid var(--line);border-radius:8px;-webkit-box-shadow:0 3px 0 var(--lip);box-shadow:0 3px 0 var(--lip)
}
.dice TD{padding:4px;background:var(--tile);border:8px solid var(--tile)
}
.dice .d{background:var(--ink);border-radius:2px
}


