
.dsquares{width:360px;margin-left:auto;margin-right:auto
}
DIV.dtable{display:inline-block;height:122px;width:122px
}
.smenu TABLE.dice{border:2px solid var(--line);-webkit-box-shadow:none;box-shadow:none
}
DIV.arrow{font-size:80px;width:100px;height:100px;line-height:1.8
}
.srow{border:2px solid var(--line);background:var(--tile);border-radius:8px;-webkit-box-shadow:0 3px 0 var(--lip);box-shadow:0 3px 0 var(--lip);padding-top:10px;margin-bottom:12px
}
.srow:active{-webkit-transform:translateY(2px);transform:translateY(2px);-webkit-box-shadow:0 1px 0 var(--lip);box-shadow:0 1px 0 var(--lip)
}
.passed{background:var(--level)
}


